//! Differential ratchet for
//! `src/engine/battleScriptNormalisebuffsOpcode.ts`. Expected complete
//! projected results and controls are generated by invoking the canonical
//! TypeScript opcode handler; regenerate with node --experimental-strip-types
//! core-rs/tools/gen-battle-script-normalisebuffs-vectors.mjs.

use std::collections::BTreeSet;

use factory_core::battle_script_normalisebuffs::{
    apply_battle_script_normalisebuffs, BattleScriptNormalisebuffsBattlerState,
    BattleScriptNormalisebuffsControl, BattleScriptNormalisebuffsOutcome,
    BattleScriptNormalisebuffsRules, BATTLE_SCRIPT_NORMALISEBUFFS_BATTLER_COUNT,
    BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE, BATTLE_SCRIPT_NORMALISEBUFFS_STAT_STAGE_COUNT,
};
use factory_core::battle_script_normalisebuffs_vectors_gen::{
    BattleScriptNormalisebuffsVectorCase, BattleScriptNormalisebuffsVectorState,
    BATTLE_SCRIPT_NORMALISEBUFFS_BRANCH_CENSUS, BATTLE_SCRIPT_NORMALISEBUFFS_CASES,
    BATTLE_SCRIPT_NORMALISEBUFFS_CATEGORY_CENSUS, BATTLE_SCRIPT_NORMALISEBUFFS_DOMAIN_CENSUS,
    BATTLE_SCRIPT_NORMALISEBUFFS_NON_NEUTRAL_TARGET_DOMAIN,
    BATTLE_SCRIPT_NORMALISEBUFFS_ROW_DOMAIN, BATTLE_SCRIPT_NORMALISEBUFFS_SIGNED_S8_EDGE_DOMAIN,
    BATTLE_SCRIPT_NORMALISEBUFFS_STAT_DOMAIN, BATTLE_SCRIPT_NORMALISEBUFFS_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptNormalisebuffsVectorState) -> BattleScriptNormalisebuffsRules {
    BattleScriptNormalisebuffsRules {
        battlers: value
            .stat_stages
            .map(|stat_stages| BattleScriptNormalisebuffsBattlerState { stat_stages }),
    }
}

fn vector_state(value: BattleScriptNormalisebuffsRules) -> BattleScriptNormalisebuffsVectorState {
    BattleScriptNormalisebuffsVectorState {
        stat_stages: value.battlers.map(|battler| battler.stat_stages),
    }
}

#[test]
fn complete_projected_outputs_controls_and_input_preservation_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_NORMALISEBUFFS_CASES.len(), 35);
    for (case_index, case) in BATTLE_SCRIPT_NORMALISEBUFFS_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptNormalisebuffsVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();

    for application in 0..case.applications {
        let prior = current;
        let outcome = apply_battle_script_normalisebuffs(&current);
        actual_controls.push(outcome.control);
        assert_transition_shape(case_index, case, application, prior, outcome);
        current = outcome.rules;
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    assert_eq!(
        actual_controls.as_slice(),
        case.controls,
        "case {case_index} {}: canonical control sequence",
        case.label,
    );
    assert_eq!(
        actual_controls.len(),
        usize::from(case.applications),
        "case {case_index} {}: unconditional advance sequence stopped early",
        case.label,
    );
    assert_eq!(
        vector_state(current),
        case.expected,
        "case {case_index} {}: complete projected output",
        case.label,
    );
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptNormalisebuffsVectorCase,
    application: u8,
    prior: BattleScriptNormalisebuffsRules,
    outcome: BattleScriptNormalisebuffsOutcome,
) {
    assert_eq!(
        outcome.control,
        BattleScriptNormalisebuffsControl::Advance,
        "case {case_index} {} application {application}: Haze must advance",
        case.label,
    );
    for battler in 0..BATTLE_SCRIPT_NORMALISEBUFFS_BATTLER_COUNT {
        for stat in 0..BATTLE_SCRIPT_NORMALISEBUFFS_STAT_STAGE_COUNT {
            assert_eq!(
                outcome.rules.battlers[battler].stat_stages[stat],
                BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE,
                "case {case_index} {} application {application}: battler {battler} stat {stat} was not normalised",
                case.label,
            );
        }
    }
    assert_eq!(
        prior.battlers.len(),
        BATTLE_SCRIPT_NORMALISEBUFFS_BATTLER_COUNT,
        "case {case_index} {}: input battler dimension drifted",
        case.label,
    );
}

#[test]
fn dense_matrix_visits_all_four_by_eight_cells_and_signed_s8_edges() {
    let matrix = BATTLE_SCRIPT_NORMALISEBUFFS_CASES
        .iter()
        .filter(|case| case.category == "all-battler-stat-position-matrix")
        .collect::<Vec<_>>();
    assert_eq!(
        matrix.len(),
        BATTLE_SCRIPT_NORMALISEBUFFS_BATTLER_COUNT * BATTLE_SCRIPT_NORMALISEBUFFS_STAT_STAGE_COUNT,
    );

    let observed_cells = matrix
        .iter()
        .map(|case| {
            let (battler, stat) = case
                .targeted_cell
                .unwrap_or_else(|| panic!("matrix case {} lacks a targeted cell", case.label));
            assert_ne!(
                case.initial.stat_stages[usize::from(battler)][usize::from(stat)],
                BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE,
                "matrix case {} must begin non-neutral at its target",
                case.label,
            );
            assert_eq!(
                case.expected.stat_stages[usize::from(battler)][usize::from(stat)],
                BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE,
                "matrix case {} did not normalise its target",
                case.label,
            );
            (battler, stat)
        })
        .collect::<BTreeSet<_>>();
    let expected_cells = BATTLE_SCRIPT_NORMALISEBUFFS_ROW_DOMAIN
        .into_iter()
        .flat_map(|battler| {
            BATTLE_SCRIPT_NORMALISEBUFFS_STAT_DOMAIN
                .into_iter()
                .map(move |stat| (battler, stat))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed_cells, expected_cells);

    let target_values = matrix
        .iter()
        .map(|case| {
            let (battler, stat) = case.targeted_cell.expect("matrix targeted cell");
            case.initial.stat_stages[usize::from(battler)][usize::from(stat)]
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(
        target_values,
        BATTLE_SCRIPT_NORMALISEBUFFS_NON_NEUTRAL_TARGET_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );

    let signed_edges = BATTLE_SCRIPT_NORMALISEBUFFS_CASES
        .iter()
        .flat_map(|case| case.initial.stat_stages)
        .flatten()
        .collect::<BTreeSet<_>>();
    assert_eq!(
        signed_edges,
        BATTLE_SCRIPT_NORMALISEBUFFS_SIGNED_S8_EDGE_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );
}

#[test]
fn mixed_rows_all_neutral_idempotence_and_repeated_application_are_pinned() {
    let mixed = BATTLE_SCRIPT_NORMALISEBUFFS_CASES
        .iter()
        .find(|case| case.label == "mixed_signed_rows_all_edges_normalise_together")
        .expect("mixed signed rows vector");
    assert_eq!(
        mixed.controls,
        &[BattleScriptNormalisebuffsControl::Advance]
    );
    assert_eq!(
        mixed
            .initial
            .stat_stages
            .into_iter()
            .flatten()
            .collect::<BTreeSet<_>>(),
        BATTLE_SCRIPT_NORMALISEBUFFS_SIGNED_S8_EDGE_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );
    assert_eq!(
        mixed.expected.stat_stages,
        [[BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE; 8]; 4],
    );

    let neutral = BATTLE_SCRIPT_NORMALISEBUFFS_CASES
        .iter()
        .find(|case| case.label == "all_neutral_rows_are_idempotent_and_advance")
        .expect("all-neutral vector");
    assert_eq!(neutral.branch, "advance");
    assert_eq!(
        neutral.controls,
        &[BattleScriptNormalisebuffsControl::Advance]
    );
    assert_eq!(neutral.initial, neutral.expected);
    assert_eq!(
        neutral.initial.stat_stages,
        [[BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE; 8]; 4],
    );

    let repeated = BATTLE_SCRIPT_NORMALISEBUFFS_CASES
        .iter()
        .find(|case| {
            case.label == "repeated_application_is_value_idempotent_and_advances_each_time"
        })
        .expect("repeated vector");
    assert_eq!(repeated.applications, 2);
    assert_eq!(repeated.branch, "advance-then-advance");
    assert_eq!(
        repeated.controls,
        &[
            BattleScriptNormalisebuffsControl::Advance,
            BattleScriptNormalisebuffsControl::Advance,
        ],
    );
    assert_eq!(
        repeated.expected.stat_stages,
        [[BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE; 8]; 4],
    );
}

#[test]
fn fixed_four_battler_eight_stage_dimensions_and_source_constant_are_retained() {
    assert_eq!(BATTLE_SCRIPT_NORMALISEBUFFS_BATTLER_COUNT, 4);
    assert_eq!(BATTLE_SCRIPT_NORMALISEBUFFS_STAT_STAGE_COUNT, 8);
    assert_eq!(BATTLE_SCRIPT_NORMALISEBUFFS_DEFAULT_STAT_STAGE, 6);
    assert_eq!(BATTLE_SCRIPT_NORMALISEBUFFS_ROW_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_NORMALISEBUFFS_STAT_DOMAIN,
        [0, 1, 2, 3, 4, 5, 6, 7],
    );
    assert_eq!(
        BATTLE_SCRIPT_NORMALISEBUFFS_SIGNED_S8_EDGE_DOMAIN,
        [-128, -1, 0, 5, 6, 7, 127],
    );
    let typed_rows: [[i8; 8]; 4] = BATTLE_SCRIPT_NORMALISEBUFFS_CASES[0].initial.stat_stages;
    assert_eq!(typed_rows.len(), BATTLE_SCRIPT_NORMALISEBUFFS_BATTLER_COUNT);
    assert!(typed_rows
        .iter()
        .all(|row| row.len() == BATTLE_SCRIPT_NORMALISEBUFFS_STAT_STAGE_COUNT));
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_NORMALISEBUFFS_DOMAIN_CENSUS,
        [
            ("battler-rows", 4),
            ("stat-stage-slots-per-row", 8),
            ("total-battler-stat-cells", 32),
            ("signed-s8-values", 256),
            ("signed-s8-edge-values", 7),
            ("non-neutral-target-values", 6),
            ("default-stat-stage-write-value", 1),
            ("application-count-values", 2),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_NORMALISEBUFFS_CATEGORY_CENSUS,
        [
            ("all-battler-stat-position-matrix", 32),
            ("all-neutral-idempotence", 1),
            ("mixed-signed-rows", 1),
            ("repeated-application", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_NORMALISEBUFFS_BRANCH_CENSUS,
        [("advance", 34), ("advance-then-advance", 1)],
    );
    assert_eq!(
        BATTLE_SCRIPT_NORMALISEBUFFS_VECTOR_CORPUS_SHA256,
        "294dac1f672c6888bbc0d7bfe2adebc4c8b0928e22abfaf9860efd08a85cd602",
    );
}
